mapper.select:
SELECT 
FROM exercise_session
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND exercise_date >= #{from}
  AND exercise_date <= #{to}
  AND is_deleted = 0
ORDER BY exercise_date ASC, started_at ASC, gmt_created ASC

SELECT type_code
FROM exercise_session
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND exercise_date >= #{since}
  AND is_deleted = 0
GROUP BY type_code
ORDER BY COUNT(1) DESC, MAX(started_at) DESC
LIMIT #{limit}
